const j = $input.first().json || {};
const twilio = $('Webhook Twilio Voice').first().json; const q = twilio.query || {}; const latestSpeech = String(twilio.body?.SpeechResult || '').trim(); const speech = [String(q.pendingTitle || '').trim(), latestSpeech].filter(Boolean).join('. ').trim();
let raw = j.output ?? j.mergedResponse ?? j.content?.parts?.map(p => p.text || '').join('') ?? j.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('') ?? '';
let a = {};
try {
  if (typeof raw === 'object' && raw !== null) a = raw;
  else a = JSON.parse(String(raw).replace(/^\x60+(?:json)?\s*/i, '').replace(/\x60+$/,'').trim());
} catch(e) { a = {}; }
if (!a || typeof a !== 'object' || Array.isArray(a)) a = {};
const title = String(a.title || '').trim().slice(0, 200);
const description = String(a.description || '').trim().slice(0, 500);
let dueDate = String(a.dueDate || q.pendingDue || '').trim();
let time = String(a.time || '').trim();
const spokenLower = speech.toLowerCase();
const stop = new Set(['add','task','new','remind','reminder','please','about','that','this','will','want','need','have','make','create','set','the','for','and','with','from','today','tomorrow','priority','high','medium','low','week','next','morning','afternoon','evening','tonight','later','every','at','you','your','mine','my','are','call','finish','complete','do','an','it','to','of','on','in','is','a','me','i']);
const words = s => (s.toLowerCase().match(/[a-z0-9]+/g) || []).filter(t => t.length > 2 && !stop.has(t));
const spokenWords = new Set(words(speech));
const meaningfulTitle = words(title);
let errorMessage = '';
if (!speech || !title) errorMessage = 'I did not catch your task. Please say add task followed by the task name.';
else if (!meaningfulTitle.length || !meaningfulTitle.some(t => spokenWords.has(t))) errorMessage = 'I could not reliably match that task to what you said. Please repeat the task name.';
const now = $now.setZone('Asia/Kolkata');
if (/\btomorrow\b/i.test(speech)) dueDate = now.plus({days:1}).toFormat('yyyy-MM-dd');
else if (/\btoday\b/i.test(speech)) dueDate = now.toFormat('yyyy-MM-dd');
if (dueDate) {
  const ok = /^\d{4}-\d{2}-\d{2}$/.test(dueDate) && !isNaN(Date.parse(dueDate)) && new Date(dueDate).toISOString().slice(0,10) === dueDate;
  if (!ok) errorMessage = 'I could not understand the due date. Please try again.';
}
const spokenTime = latestSpeech.toLowerCase().match(/\b(?:at\s*)?(\d{1,2})(?::(\d{2}))?\s*(?:o['’]?clock\s*)?(a\.?m\.?|p\.?m\.?)\b/);
if (spokenTime) {
  let h = Number(spokenTime[1]); const m = Number(spokenTime[2] || 0);
  if (h >= 1 && h <= 12 && m < 60) {
    const pm = spokenTime[3].startsWith('p'); h = h % 12 + (pm ? 12 : 0);
    time = String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0');
  }
}
if (time && (!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))) errorMessage = 'I could not understand the task time. Please try again.';
if (!dueDate && time && q.pendingTitle) { const current=$now.setZone('Asia/Kolkata'); const t=current.toFormat('HH:mm'); dueDate=(time>t ? current : current.plus({days:1})).toFormat('yyyy-MM-dd'); }
const p = /\bhigh priority\b/i.test(latestSpeech) ? 'high' : /\blow priority\b/i.test(latestSpeech) ? 'low' : String(q.pendingPriority || a.priority || '').trim().toLowerCase();
const priority = p === 'high' ? 'High' : p === 'low' ? 'Low' : 'Medium';
const taskId = 'T-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2,6).toUpperCase();
const createdAt = now.toFormat('yyyy-MM-dd HH:mm:ss');
return [{json: {taskId,title,description,dueDate,time,priority,status:'Pending',createdAt,errorMessage}}];

const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r['Task Title'] && String(r['Status'] || '').trim().toLowerCase() === 'pending'; });
function mins(t) {
  var s = String(t || '').trim().toLowerCase();
  var pm = s.indexOf('pm') > -1; var am = s.indexOf('am') > -1;
  s = s.replace('am', '').replace('pm', '').trim();
  var parts = s.split(':'); var h = parseInt(parts[0], 10); var mi = parseInt(parts[1] || '0', 10);
  if (isNaN(h)) return 1440;
  if (pm && h < 12) h += 12; if (am && h === 12) h = 0;
  return h * 60 + (isNaN(mi) ? 0 : mi);
}
function day(r) { var d = Date.parse(String(r['Due Date'] || '')); return isNaN(d) ? 8.64e15 : d; }
var rank = { high: 0, medium: 1, low: 2 };
function pr(r) { var p = String(r['Priority'] || '').toLowerCase(); return rank[p] === undefined ? 1 : rank[p]; }
rows.sort(function (a, b) { return day(a) - day(b) || mins(a['Time']) - mins(b['Time']) || pr(a) - pr(b); });
var result;
if (rows.length === 0) {
  result = 'You have no pending tasks. Nice work!';
} else {
  var max = 7;
  var parts = rows.slice(0, max).map(function (r, idx) {
    var line = (idx + 1) + ', ' + r['Task Title'];
    if (r['Priority']) line += ', ' + String(r['Priority']).toLowerCase() + ' priority';
    if (r['Due Date']) line += ', due ' + r['Due Date'] + (r['Time'] ? ' at ' + r['Time'] : '');
    return line + '.';
  });
  result = 'You have ' + rows.length + ' pending ' + (rows.length === 1 ? 'task' : 'tasks') + '. ' + parts.join(' ');
  if (rows.length > max) result += ' And ' + (rows.length - max) + ' more.';
}
result = result.replace(/[\r\n]+/g, ' ') + ' Anything else?';
return [{ json: { say: result } }];

const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r['Task Title'] && String(r['Status'] || '').trim().toLowerCase() === 'pending'; });
// Always create a call, even when there are no pending tasks.
function day(r) { var d = Date.parse(String(r['Due Date'] || '')); return isNaN(d) ? 8.64e15 : d; }
var rank = { high: 0, medium: 1, low: 2 };
function pr(r) { var p = String(r['Priority'] || '').toLowerCase(); return rank[p] === undefined ? 1 : rank[p]; }
rows.sort(function (a, b) { return day(a) - day(b) || pr(a) - pr(b); });
var parts = rows.slice(0, 7).map(function (r, idx) {
  var line = (idx + 1) + ', ' + r['Task Title'];
  if (r['Due Date']) line += ', due ' + r['Due Date'] + (r['Time'] ? ' at ' + r['Time'] : '');
  return line + '.';
});
var msg = 'Good afternoon. You have ' + rows.length + ' pending ' + (rows.length === 1 ? 'task' : 'tasks') + '. ' + parts.join(' ') + ' You can say plan my day, or add task followed by the details.';
msg = msg.replace(/[\r\n]+/g, ' ').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
var twiml = '<Response><Gather input="speech" action="https://YOUR_N8N_DOMAIN/webhook/voice-task" method="POST" speechTimeout="auto" language="en-IN"><Say language="en-IN">' + msg + '</Say></Gather><Say language="en-IN">Goodbye.</Say></Response>';
return [{ json: { twiml: twiml } }];

const rows = $input.all().map(i=>i.json).filter(r=>r && r['Task Title'] && String(r['Status']||'').trim().toLowerCase()==='pending');
const msg = 'Good afternoon. This is your task planner. You have ' + rows.length + ' pending tasks. Tell me the new task you want to add, in your own words. I will ask for the time separately. Or say list my tasks, or plan my day.';
const twiml = '<Response><Gather input="speech" action="https://YOUR_N8N_DOMAIN/webhook/voice-task" method="POST" language="en-IN" speechTimeout="auto" hints="task name, add task, Python developer, prepare interview questions, four P M, list my tasks, plan my day"><Say language="en-IN">' + msg + '</Say></Gather><Say language="en-IN">I did not hear a response. Goodbye.</Say></Response>';
return [{json:{twiml}}];

const t = $input.first().json;
const action = 'https://YOUR_N8N_DOMAIN/webhook/voice-task?pendingTitle=' + encodeURIComponent(String(t.title||'').slice(0,180)) + '&pendingDue=' + encodeURIComponent(String(t.dueDate||'').slice(0,15)) + '&pendingPriority=' + encodeURIComponent(String(t.priority||'Medium').slice(0,10));
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const prompt = 'I heard: ' + t.title + '. At what time do you want to do it? For example, say at 4 P M. Or say no time to save without a specific time.';
const twiml = '<Response><Gather input="speech" action="' + esc(action) + '" method="POST" language="en-IN" speechTimeout="auto"><Say language="en-IN">' + esc(prompt) + '</Say></Gather><Say language="en-IN">I did not hear the time. Please tell me the task again on your next call. Goodbye.</Say></Response>';
return [{json:{twiml}}];
